CREATE TABLE IF NOT EXISTS activity_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL, activity TEXT NOT NULL, minutes INTEGER NOT NULL CHECK (minutes > 0), distance_km NUMERIC, calories NUMERIC NOT NULL DEFAULT 0 CHECK (calories >= 0), intensity TEXT NOT NULL DEFAULT 'moderate', source TEXT NOT NULL DEFAULT 'estimated', method TEXT NOT NULL DEFAULT 'MET × weight × duration', log_date DATE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now())